+        self.start_token
+    }
+    pub fn end_token(&self) -> u64 {
+        self.end_token
+    }
+    pub fn contains_ancestor(&self, key: &ContentKey, end: u64) -> bool {
+        let mut node = Some(self);
+        while let Some(n) = node {
+            if &n.key == key && n.end_token == end {
+                return true;
+            }
+            node = n.parent.as_deref();
+        }
+        false
+    }
