+    pub fn finish_task_with_cascade(
+        &mut self,
+        task: &SessionIdentity,
+        revision: u64,
+        cascade: bool,
+    ) -> Result<Cleanup, IndexError> {
+        if self.tombstones.contains(task) {
+            return Ok(Cleanup::default());
+        }
