+                    self.material_checksums.remove(key);
+                    if let Some(tokens) = self.material.remove(key) {
+                        self.material_bytes -= tokens.len() * std::mem::size_of::<u32>();
+                    }
+                    false
+                }
+            });
+            if self.contents.len() == old {
+                break;
+            }
+        }
+    }
