+    let mut fences = ObservationFence::new(4, 128);
+    fences.bind_owner(worker.clone(), "e".into()).unwrap();
+    let ticket = fences.begin_query(&worker).unwrap();
+    fences
+        .install_complete_snapshot(&ticket, ticket.owner_epoch(), CacheEventVersion(1))
+        .unwrap();
+    assert_eq!(
+        fences.observe_event(&worker, "e", CacheEventVersion(3)),
+        Ok(EventDisposition::Gap)
+    );
+    assert_eq!(
+        fences
+            .confirm_stream(
+                &worker,
+                "e",
+                CacheEventVersion(3),
+                actual(&scope, 4),
+                100,
+                Provenance::KvEvent
+            )
+            .unwrap_err(),
+        ObservationError::IncompleteStream
+    );
+    let query = fences.begin_query(&worker).unwrap();
+    let partial = fences
+        .confirm_query(&query, query.owner_epoch(), actual(&scope, 4), 100)
+        .unwrap();
+    assert!(fences.is_current(&partial));
+    assert!(!fences.stream_complete(&worker));
+    assert_eq!(
+        fences.install_complete_snapshot(&query, query.owner_epoch(), CacheEventVersion(2)),
+        Err(ObservationError::StaleEvidence)
+    );
+    assert_eq!(
+        fences.observe_event(&worker, "e", CacheEventVersion(4)),
+        Ok(EventDisposition::Applied)
+    );
+    assert!(!fences.is_current(&partial));
+    assert_eq!(
+        fences.install_complete_snapshot(&query, query.owner_epoch(), CacheEventVersion(4)),
+        Err(ObservationError::StaleEvidence)
+    );
+    let fresh = fences.begin_query(&worker).unwrap();
+    fences
+        .install_complete_snapshot(&fresh, fresh.owner_epoch(), CacheEventVersion(4))
+        .unwrap();
+    assert!(fences.stream_complete(&worker));
+    let current = fences
+        .confirm_stream(
+            &worker,
+            "e",
+            CacheEventVersion(4),
+            actual(&scope, 4),
+            500,
+            Provenance::IndexerSnapshot,
+        )
+        .unwrap();
+    assert_eq!(
+        fences.observe_event(&worker, "e", CacheEventVersion(4)),
+        Ok(EventDisposition::DuplicateOrStale)
+    );
+    assert!(fences.is_current(&current));
+    fences.mark_gap(&worker, "e").unwrap();
+    assert!(!fences.is_current(&current));
+}
