+fn stale_provider_views_become_unknown_and_query_responses_must_match_the_owner_epoch() {
+    let (_index, scope) = scope_fixture();
+    let worker = owner("worker");
+    let mut fence = ObservationFence::new(1, 128);
+    fence.bind_owner(worker.clone(), "current".into()).unwrap();
+    let ticket = fence.begin_query(&worker).unwrap();
+    assert_eq!(
+        fence
+            .confirm_query(&ticket, "old", actual(&scope, 8), 100)
+            .unwrap_err(),
+        ObservationError::WrongEpoch
+    );
+    assert_eq!(
+        fence.install_complete_snapshot(&ticket, "old", CacheEventVersion(10)),
+        Err(ObservationError::WrongEpoch)
+    );
+    let confirmed = fence
+        .confirm_query(&ticket, "current", actual(&scope, 4), 100)
+        .unwrap();
+    let pending = ExpectedPlacement {
+        task: session("task"),
+        operation_id: "op".into(),
+        destination: worker.clone(),
+        scope: actual(&scope, 8),
+        expires_at: 200,
+    };
+    let mut view = LocationView {
+        confirmed: vec![confirmed],
+        expected: vec![pending],
+        unknown: vec![],
+    };
+    fence.mark_gap(&worker, "current").unwrap();
+    view.revalidate(&fence);
+    assert!(view.confirmed.is_empty());
+    assert_eq!(view.unknown.len(), 1);
+    assert_eq!(view.expected.len(), 1);
+    assert_eq!(view.unknown[0].scope.end_token(), 4);
+    assert_eq!(view.unknown[0].reason, UnknownReason::StaleEvidence);
+    view.revalidate(&fence);
+    assert_eq!(view.unknown.len(), 1);
+}

