+        let mut ids = BTreeSet::new();
+        let mut missing = Vec::new();
+        for resolved in frozen.known_scope() {
+            let prefix = match self.index.materialize(resolved.scope()) {
+                Ok(p) => p,
+                Err(gaps) => {
