+                    continue;
+                }
+            };
+            let Some((url, caps)) = available.iter().find(|(_, c)| {
+                c.compatible(&prefix)
+                    && if action == "sglang.pin" {
+                        c.public["actions"][action]
+                            .as_array()
+                            .is_some_and(|a| a.iter().any(|v| v == "1.0"))
