+        assert_eq!(depths[0].0.as_ref(), engine.url);
+        assert_eq!(depths[0].1, 4);
+        assert_eq!(
+            router.tree.pending().followed(),
+            1,
+            "routing path reorg={reorg}"
+        );
+        assert!(engine.state.lock().unwrap().commands.is_empty());
+    }
